// Copies the HTML reports generated by bazos-mcp into public/reports/, builds src/data/reports.json (the catalogue
// the site renders), downloads a photo for new models and adds the Férovka look + photo header to every report.
// Run after every new analysis: `npm run sync`, then commit & push.
import fs from "node:fs";
import path from "node:path";
import { fetchImages } from "./fetch-images.mjs";

const root = path.resolve(import.meta.dirname, "..");
const src = path.resolve(process.env.REPORTS_DIR ?? path.join(root, "..", "data", "reports"));
const dst = path.join(root, "public", "reports");
fs.mkdirSync(dst, { recursive: true });
fs.mkdirSync(path.join(root, "src", "data"), { recursive: true });

const strip = (s) => s.replace(/<[^>]+>/g, "").replace(/&amp;/g, "&").replace(/\s+/g, " ").trim();
const num = (s) => Number(String(s).replace(/[^\d]/g, "")) || null;
const esc = (s) => String(s).replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/"/g, "&quot;");

// 1) catalogue
const reports = [];
const sources = {};
for (const file of fs.readdirSync(src).filter((f) => f.endsWith(".html"))) {
  const html = fs.readFileSync(path.join(src, file), "utf8");
  const slug = file.replace(/(-analyza)?\.html$/, "");
  const title = strip(html.match(/<title>(.*?)<\/title>/s)?.[1] ?? slug);
  const lead = strip(html.match(/<p class="lead">(.*?)<\/p>/s)?.[1] ?? "");
  const kpis = [...html.matchAll(/<div class="kpi"><div class="v">(.*?)<\/div><div class="l">(.*?)<\/div><\/div>/gs)]
    .map((m) => ({ value: strip(m[1]), label: strip(m[2]) }));
  const d = lead.match(/\((\d{1,2})\. ?(\d{1,2})\. ?(\d{4})\)/);
  const date = d
    ? `${d[3]}-${d[2].padStart(2, "0")}-${d[1].padStart(2, "0")}`
    : fs.statSync(path.join(src, file)).mtime.toISOString().slice(0, 10);
  const comparison = slug.startsWith("porovnanie");
  const name = comparison ? title : title.split(" – ")[0];
  const kpi = (re) => kpis.find((k) => re.test(k.label))?.value ?? null;
  reports.push({
    slug,
    file,
    name,
    brand: comparison ? "Porovnanie" : name.split(" ")[0],
    model: comparison ? name : name.split(" ").slice(1).join(" "),
    kind: comparison ? "comparison" : "model",
    date,
    summary: lead
      .replace(/\s*Každé auto sme porovnali.*$/, "")
      .replace(/ (na|z) auto\.bazos\.sk a www\.autobazar\.eu \([^)]*\)/, (_, p) => (p === "na" ? " na bazoši a autobazar.eu" : " z bazoša a autobazar.eu")),
    ads: num(kpis[0]?.value) ?? num(lead.match(/Porovnanie ([\d\s]+) /)?.[1]),
    median: kpi(/medián ceny/),
    r2: kpi(/vysvetlí model/),
  });
  sources[file] = html;
}
reports.sort((a, b) => (a.kind === b.kind ? 0 : a.kind === "comparison" ? -1 : 1) || b.date.localeCompare(a.date) || a.name.localeCompare(b.name, "sk"));
fs.writeFileSync(path.join(root, "src", "data", "reports.json"), JSON.stringify(reports, null, 2));

// 2) photos (needs internet; without it the existing photos are kept)
let images = {};
try {
  images = await fetchImages(reports);
} catch (e) {
  console.warn(`! photos not refreshed: ${e.message}`);
  const f = path.join(root, "src", "data", "images.json");
  if (fs.existsSync(f)) images = JSON.parse(fs.readFileSync(f, "utf8"));
}
// a comparison shows the photos of the models it compares (whole words: BMW "3" is not in "i30")
const wordIn = (text, word) => text.toLowerCase().split(/[^\p{L}\p{N}]+/u).includes(word.toLowerCase());
const photosFor = (r) =>
  r.kind === "model"
    ? [images[r.slug]].filter((i) => i?.src)
    : Object.values(
        reports
          .filter((m) => m.kind === "model" && wordIn(r.name, m.model.split(" ")[0]))
          // one photo per model: "Octavia" and "Octavia combi" both match – keep the main report (shortest slug)
          .reduce((best, m) => {
            const k = m.model.split(" ")[0].toLowerCase();
            if (!best[k] || m.slug.length < best[k].slug.length) best[k] = m;
            return best;
          }, {}),
      )
        .map((m) => images[m.slug])
        .filter((i) => i?.src);

// 3) themed reports with a photo header
const FONTS =
  '<link rel="preconnect" href="https://fonts.googleapis.com"><link rel="preconnect" href="https://fonts.gstatic.com" crossorigin>' +
  '<link rel="stylesheet" href="https://fonts.googleapis.com/css2?family=Manrope:wght@400;500;600;700;800&display=swap">';
const THEME = fs.readFileSync(path.join(root, "scripts", "report-theme.css"), "utf8");
// nearest-point chart → ad links (see the file); "</script" can't occur inside it
const CHART_JS = fs.readFileSync(path.join(root, "scripts", "report-chart.js"), "utf8");
// one filter bar (year, price from/to, km, fuel…) for the chart and the ranking of every model report (see the file)
const FILTERS_JS = fs.readFileSync(path.join(root, "scripts", "report-filters.js"), "utf8");
for (const r of reports) {
  const photos = photosFor(r);
  const hero = photos.length
    ? `<figure class="fv-hero${photos.length > 1 ? " fv-collage" : ""}">` +
      photos.map((p) => `<img src="${p.src}" alt="">`).join("") +
      `<figcaption>Foto: ${photos.map((p) => `<a href="${esc(p.source)}" target="_blank" rel="noopener">${esc(p.author)}</a>, ${esc(p.license)}`).join(" · ")} (Wikimedia Commons)</figcaption></figure>`
    : "";
  const html = sources[r.file]
    .replace(/<!-- ferovka-theme -->[\s\S]*?<!-- \/ferovka-theme -->/g, "")
    .replace("</head>", `<!-- ferovka-theme -->${FONTS}<style id="ferovka-theme">${THEME}</style><!-- /ferovka-theme -->\n</head>`)
    .replace(/<main>/, `<main><!-- ferovka-theme -->${hero}<!-- /ferovka-theme -->`)
    .replace(/<\/body>(?![\s\S]*<\/body>)/, () =>
      `<!-- ferovka-theme --><script defer src="/analytics-config.js"></script><script defer src="/analytics.js"></script><script id="ferovka-chart">${CHART_JS}</script>` +
      (r.kind === "model" ? `<script id="ferovka-filters">${FILTERS_JS}</script>` : "") +
      `<!-- /ferovka-theme -->\n</body>`);
  fs.writeFileSync(path.join(dst, r.file), html);
}
console.log(`synced ${reports.length} reports from ${src}`);
